    "content": "当地时间7月27日，派拉蒙天空之舞首席执行官大卫·埃里森表示，公司对以约1100亿美元收购华纳兄弟探索的交易“高度有信心”，尽管该交易目前面临法律挑战。埃里森表示，包括美国、欧盟和韩国在内的65个司法辖区已批准或决定不阻止该交易。不过，美国12个州以及美国编剧工会已提起诉讼，试图阻止交易，认为合并可能削弱影视行业竞争并推高消费者成本。美国演员工会也支持相关诉讼，并表示只有在获得不会减少影视制作规模、不影响新闻业务岗位等具有法律约束力的承诺后，才可能支持交易。（界面）"
