    "author": "孔德淇/工人日报",
    "description": "据“新华日报”微信公众号报道，7月25日晚，某网络名人在社交媒体发文怒斥当下电视机的产品设计。他表示，自己为家中老人更换了两次电视机，老人都用不明白，包括使用厂商推出的所谓“长辈模式”，最终只能加装了老人至少会用的IPTV机顶盒，“明明网络节目上有看不完的电视剧，还是只能让她看传统电视频道……”对此，不少网友表示了赞同，称“连年轻人也时常迷糊”。 近年来，智能电视硬件迭代飞速，高清大屏、超薄机身、海量影音内容已成标配，各类智能功能不断丰…",
    "content": "据“新华日报”微信公众号报道，7月25日晚，某网络名人在社交媒体发文怒斥当下电视机的产品设计。他表示，自己为家中老人更换了两次电视机，老人都用不明白，包括使用厂商推出的所谓“长辈模式”，最终只能加装了老人至少会用的IPTV机顶盒，“明明网络节目上有看不完的电视剧，还是只能让她看传统电视频道……”对此，不少网友表示了赞同，称“连年轻人也时常迷糊”。 近年来，智能电视硬件迭代飞速，高清大屏、超薄机身、海量影音内容已成标配，各类智能功能不断丰富家庭娱乐场景。但硬件升级之外，基础使用体验却有些走偏，尤其是针对老年群体的适老…"
