    "description": "近日，磷酸铁锂龙头湖南裕能发布调价函，宣布全系产品价格上调2000元/吨，带动行业涨价情绪升温。记者在采访中了解到，龙头企业率先调价后，业内多家企业也在同步酝酿涨价。本轮磷酸铁锂涨价由两方面因素共同驱动：一方面是成本端，以硫磺为代表的上游原材料价格大涨，上游转嫁成本意愿迫切；另一方面是市场端，下游需求走强，高端产品供不应求。业内普遍认为，成本波动将进一步加大磷酸铁锂行业两极分化趋势，布局具备一体化、高端产能，且深度绑定大客户的企业将在市…",
    "content": "近日，磷酸铁锂龙头湖南裕能发布调价函，宣布全系产品价格上调2000元/吨，带动行业涨价情绪升温。记者在采访中了解到，龙头企业率先调价后，业内多家企业也在同步酝酿涨价。本轮磷酸铁锂涨价由两方面因素共同驱动：一方面是成本端，以硫磺为代表的上游原材料价格大涨，上游转嫁成本意愿迫切；另一方面是市场端，下游需求走强，高端产品供不应求。业内普遍认为，成本波动将进一步加大磷酸铁锂行业两极分化趋势，布局具备一体化、高端产能，且深度绑定大客户的企业将在市场竞争中更具优势。更进一步，本轮涨价或将打开产业上下游议价博弈空间，改写行业定价…"
