    "description": "芝加哥商品交易所集团周一推出了基于55只美国股票的现金结算个股期货，以及基于22只股票的微型合约，标志着该交易所进军一个旨在让投资者全天候进行杠杆式多空交易的市场。这些合约在CME的Globex平台上从周日晚间至周五下午进行交易，每日有一个小时的维护休市时间，使投资者能够在美国常规股市交易时间之外对财报和其他影响市场的事件做出反应。产品阵容包括与SpaceX相关的期货，此外还包括美光科技、英伟达、特斯拉和苹果。（新浪财经）",
