    "description": "眼下正是民航暑运旺季，不少旅客关注航班超售问题。 近日，北京、天津和河北三地消协组织开展航班超售认知专项调查，结果显示：虽然近九成旅客听说过航班超售，但近七成旅客并不能够完整掌握航班超售规则；仅近三成旅客清晰知晓超售后全额退改签、食宿安置、经济补偿等相关权益；购票过程中，超七成旅客反映超售风险提示文字过小、位置隐蔽、辨识度低，超半数旅客认为告知文字表述模糊。 7月24日，京津冀三地消协组织就航班超售问题，约谈中国国际航空等10家航空公司…",
