    "content": "新华社纽约7月27日电 纽约股市三大股指27日涨跌不一。 截至当天收盘，道琼斯工业平均指数比前一交易日上涨262.83点，收于52210.08点，涨幅为0.51%；标准普尔500种股票指数上涨1.20点，收于7413.18点，涨幅为0.02%；纳斯达克综合指数下跌43.74点，收于24932.08点，跌幅为0.18%。 板块方面，标普500指数十一大板块七涨四跌。必需消费品板块和通信服务板块分别以1.58%和1.46%的涨幅领涨，能源板块和公用事业板块分别以2.01%和1.32%的跌幅领跌。"
