    "content": "新华社旧金山7月27日电（记者吴晓凌）美国华盛顿州西雅图市市长凯蒂·威尔逊27日表示，该市日前发生的枪击事件造成3人死亡、4人受伤，警方已逮捕一名15岁的嫌疑人。 据西雅图警方公布的消息，枪击发生于26日18时许，地点位于“西雅图中心”附近，当地正在举办美食节，现场聚集大批游客。初步调查显示，两名嫌疑人互相开枪，致7人中弹，其中两人当场死亡，另一人送医后不治身亡。4名伤者中包括一名2岁儿童。 当地警方说，已缴获两把枪支，调查仍在继续，目前没有迹象表明公众面临持续威胁。 威尔逊说，被捕嫌疑人27日下午将首次出庭，另一…"
