    "content": "新华社多伦多7月27日电（记者林威）据加拿大媒体报道，当地时间27日凌晨，美国驻多伦多总领事馆遭枪击，这是该建筑今年第二次遭袭。 多伦多市警方表示，枪击发生于当天4时45分许。一名值班警员听到枪声后，发现一辆无牌照的白色轿车正高速驶离现场。由于缺乏空中支援且嫌疑车辆车速过快，警方出于安全考量，在高速公路附近暂停追捕。 总领馆外墙受损，无人员伤亡。 美国驻多伦多总领事馆上一次遭到枪击发生在今年3月10日凌晨。有媒体报道说，警方随后逮捕了三名犯罪嫌疑人，并在该总领馆附近部署一支安保队伍。此次枪击事件正是这支安保队伍中的…"
