    "author": "周蕊,戚新源,方喆",
    "description": "新华社上海7月27日电（周蕊、戚新源）记者从27日在此间举行的第九届中国国际进口博览会新闻通气会上了解到，第九届进博会各项筹备工作进展顺利，已有57个国家和3个国际组织确认参加国家展。企业商业展已签约的展览面积超过34万平方米，169家企业和30家境外组展机构成为进博会九届“全勤生”。 中国国际进口博览局党委书记、副局长吴政平介绍，本届进博会已有57个国家和3个国际组织确认参加国家展，摩尔多瓦、罗马尼亚和联合国开发计划署将首次参展。其中…",
    "content": "新华社上海7月27日电（周蕊、戚新源）记者从27日在此间举行的第九届中国国际进口博览会新闻通气会上了解到，第九届进博会各项筹备工作进展顺利，已有57个国家和3个国际组织确认参加国家展。企业商业展已签约的展览面积超过34万平方米，169家企业和30家境外组展机构成为进博会九届“全勤生”。 中国国际进口博览局党委书记、副局长吴政平介绍，本届进博会已有57个国家和3个国际组织确认参加国家展，摩尔多瓦、罗马尼亚和联合国开发计划署将首次参展。其中，中国馆将以“开创新局面 共赢新未来”为主题，全面展示“十五五”时期中国经济社会…"
