    "description": "新华社赫尔辛基7月27日电（记者朱昊晨 徐谦）芬兰工业联合会国际贸易和贸易政策主任蒂莫·沃里27日表示，美国自身尚未完全履行国际劳工组织框架下的义务，却以“强迫劳动”为名对其他经济体加征关税，凸显美方双重标准。 沃里当天接受芬兰国家广播公司采访时说，特朗普政府为单方面加征关税遍寻“法律依据”，最终从一项上世纪70年代的法律中搬出“强迫劳动”这一理由，这一做法十分荒谬。 美国贸易代表办公室23日发布公告，宣布依据《1974年贸易法》第30…",
    "content": "新华社赫尔辛基7月27日电（记者朱昊晨 徐谦）芬兰工业联合会国际贸易和贸易政策主任蒂莫·沃里27日表示，美国自身尚未完全履行国际劳工组织框架下的义务，却以“强迫劳动”为名对其他经济体加征关税，凸显美方双重标准。 沃里当天接受芬兰国家广播公司采访时说，特朗普政府为单方面加征关税遍寻“法律依据”，最终从一项上世纪70年代的法律中搬出“强迫劳动”这一理由，这一做法十分荒谬。 美国贸易代表办公室23日发布公告，宣布依据《1974年贸易法》第301条，以所谓“强迫劳动”为由，对来自60个国家和地区的进口商品征收10%至12.…"
