    "author": "hihihihihi",
    "description": "我用过中转站，也单独买过几家的服务，经常就是换过来换过去，要不就是账号被封，要不就是中转站跑路，要不就是有的模型没有。 Factory Droid 的 CLI 用起来也很顺手， 模型也比较全， 比如： Fable 5 Kimi K3 Opus 5 GPT-5.6 Sol GROK 4.5 GLM 5.2 这几个常用的都有，不用再去折腾账号了，并且随时/model 切换着用。 买了 100 美金的套餐，舒服！ 不是推广，谢谢！",
