    "content": "买了机票却不能登机，退张机票要扣97%的票款。机票超售让消费者“走不了”，天价退票费让消费者“退不起”。记者走访调查，为您揭开机票消费背后的权益“黑洞”。 机票超售：买了票却上不了飞机 2026年2月24日，消费者雯女士乘坐东航MU5426从重庆飞往上海看病。雯女士常年患有慢性病，这次好不容易约上了上海三甲医院的一个知名专家特需门诊号。她提前线上值机、正常安检，抵达登机口时却被告知航班超售，无法登机。雯女士反复说明紧急就医情况，但航空公司仅提供改签后续航班、升舱加400元现金补偿。更让她气愤的是，不少比自己晚到的旅…"
