    "content": "以前用 Claude Code 、Codex 、Grok ，其实都是单打独斗：开一堆终端，这边聊半截、那边写一半，进度散得到处都是。agent 干完一步就停在那等我回车；我去接杯水，活就卡死了。人得一直钉在电脑前，比写代码本身还累。 烦够了，我干脆把想要的工作方式做成了开源项目 ccteam ——不是再造一个新 agent ，而是把已经在用的这些 code agent 编成一支真正能协作的团队。 现在比较常见的一天是这样的：出门前丢给 Codex 一个长活；吃饭时在 Telegram （飞书也行）瞄一眼进度、补一句…"
