    "author": "",
    "description": "27/07/2026 - 17:49 周一，日本首相高市早苗在就第221届特别国会闭幕的记者会上就日中关系表示，“期待”11月在中国举行的亚太经合组织（APEC）峰会。据悉，她是在回答有关峰会期间是否有可能与中国国家主席习近平会晤的问题时作出上述表态的。 关于日中关系，高市说道：“中国是重要的邻国，自就任首相以来，我始终坚持全面推进日中战略互惠关系、构建建设性且稳定的双边关系的方针。正因为日中之间存在关切和问题，才更需要在各个层面、通过…",
    "content": "27/07/2026 - 17:49 周一，日本首相高市早苗在就第221届特别国会闭幕的记者会上就日中关系表示，“期待”11月在中国举行的亚太经合组织（APEC）峰会。据悉，她是在回答有关峰会期间是否有可能与中国国家主席习近平会晤的问题时作出上述表态的。 关于日中关系，高市说道：“中国是重要的邻国，自就任首相以来，我始终坚持全面推进日中战略互惠关系、构建建设性且稳定的双边关系的方针。正因为日中之间存在关切和问题，才更需要在各个层面、通过各种机会开展对话，增进相互理解。今后，我们将继续保持沟通，从国家利益出发，冷静、…"
