    "content": "新华社柏林7月27日电（记者车云龙）德国跑车制造商保时捷27日宣布，将于2035年前在德国再裁减5000个工作岗位。这是该公司近期又一轮大规模裁员计划，旨在降低人力成本、提升竞争力。 根据计划，此次裁员涉及保时捷总部所在地斯图加特地区的生产工厂和研发中心。与此同时，公司还宣布将采取其他成本削减措施，包括未来几年暂缓涨薪、减少奖金，以及将员工奖金与公司经营业绩进一步关联等。 此前，保时捷已宣布将在2029年前在斯图加特地区裁减约1900个岗位，另有约2000名员工的固定期限劳动合同到期后将不再续签。这意味着保时捷在德…"
