    "content": "7月27日，在澳大利亚珀斯，澳大利亚智慧能源理事会首席执行官戴维·麦克雷接受新华社记者专访。新华社发（周丹摄） 新华社澳大利亚珀斯7月27日电（记者薛艳雯 刘晓宇）博鳌亚洲论坛珀斯会议27日在澳大利亚珀斯举行，主题为“绿色转型：迈向人与地球的共同未来”。不少与会代表在接受新华社记者采访时表示，中国的绿色发展成就令人瞩目，为世界的绿色转型和可持续发展提供了宝贵经验。 “我是中国的超级粉丝！中国向清洁能源转型进展迅速。”澳大利亚提姆全球快递公司首席执行官克里斯蒂娜·霍尔盖特说。 她说，中国政府在绿色交通等方面决心明确，…"
