    "content": "新华社广州7月27日电（记者杨深深）今年是中国和东盟建立全面战略伙伴关系5周年。7月27日，20余名来自东盟的主流媒体记者和网络达人来到广东，进一步深化双方人文交流。 在广州，110千伏猎桥变电站外表洁白如玉，夜景灯光与广州塔相互映衬，被市民称作“月光宝盒”。其天台顶棚铺设的发电玻璃，年平均发电量约2万度，实现变电站的低碳节能。南方电网广东广州供电局工作人员介绍，110千伏猎桥站在传统变电站单一功能性的基础上增加了公共性和科普性。 “在来到这里之前，我没想到变电站也可以是一栋漂亮的建筑，而且还非常绿色和低碳。”来自…"
