    "content": "新华社墨尔本7月27日电（记者熊文苑 徐海静）中国驻巴布亚新几内亚大使馆27日通过微信公众号发布消息，巴新新爱尔兰省利希尔岛附近海域日前发生一起小型船只倾覆事故，遇难者中包括4名中国公民。 中国驻巴新使馆说，巴新处于多重洋流和风流系统复合影响下，水道海况复杂。近期，厄尔尼诺现象加剧风力和海浪影响，海上船只事故频发，已致多人溺水或失踪。使馆建议在巴新中国公民和机构减少非必要出海活动，注意出海和涉水安全。 使馆提醒在巴新中国公民和机构密切关注当地天气和海况预报，严格遵守海事部门安全提示和规定，选择符合安全标准的船舶，并…"
