    "content": "IT之家 7 月 27 日消息，据第一财经报道，今日，大众汽车集团发布声明称，2026 年上半年财报电话会议上，大众汽车集团管理董事会主席奥博穆就自由公平的贸易环境这一话题表态。 对于当下，欧洲正在讨论的拟对从中国进口至欧洲的混动车辆加征关税的议题， 大众集团 CEO 奥博穆 并未明确呼吁加征关税 ，而是倡导全面考量各类潜在方案，保障欧洲与全球其他地区之间形成公平的竞争环境。这其中，包括支持中国整车企业在欧洲实现本土化生产。 他同时强调，若欧盟未来最终决定加征相关关税，为维护与中国的健康贸易关系，该关税税率不应超过…"
