    "content": "27/07/2026 - 16:17 据科技媒体《信息报》援引消息人士报导称，一家总部位于上海的中国公司已开始限量生产沉浸式深紫外光刻机。这家公司计划今年生产5套系统以供交付，预计到2027年生产约20台沉浸式深紫外光刻机。 虽然这个数字可能看起来并不大，但它代表了中国在开发本土深紫外光刻机生产方面作出的重大努力，预计将能减少对荷兰芯片设备巨头阿斯麦（ASML）等第三方供应商的依赖。这家上海公司计划首先向中芯国际、长鑫存储和华虹交付，并将这些机器集成到它们的生产流程中。该消息发布后，阿斯麦股价下跌了4.6%。 由于…"
