    "description": "27/07/2026 - 17:07 欧洲消费者联合会（BEUC）及一位欧盟资深议员正敦促欧盟委员会采取行动，确保消费者在网购时不会因缴纳新关税而面临意料之外的额外费用。 7月1日，欧盟对之前免税进入欧盟的低价值电子商务进口商品征收3欧元（3.41美元）的费用。征收该关税的部分目的是为了遏制欧盟所认为的来自在线零售商的不公平竞争，并应对电商包裹数量激增的问题（预计2025年将达到58亿件）。 由31个欧洲国家的消费者组织组成的联合机构，…",
    "content": "27/07/2026 - 17:07 欧洲消费者联合会（BEUC）及一位欧盟资深议员正敦促欧盟委员会采取行动，确保消费者在网购时不会因缴纳新关税而面临意料之外的额外费用。 7月1日，欧盟对之前免税进入欧盟的低价值电子商务进口商品征收3欧元（3.41美元）的费用。征收该关税的部分目的是为了遏制欧盟所认为的来自在线零售商的不公平竞争，并应对电商包裹数量激增的问题（预计2025年将达到58亿件）。 由31个欧洲国家的消费者组织组成的联合机构，欧洲消费者组织联盟（BEUC）表示，消费者必须了解包含关税在内的总价。该联盟发现…"
