    "content": "WAIC上的“小女生” 一群十几岁的女生，出现在世界人工智能大会(WAIC)的展馆里。她们穿着天蓝色T恤，背着书包，在机器人和芯片之间穿行——看起来像是走错了片场。 但当她们开口，你就知道没有走错。 “现在的机器人大多集中于比较平整、标准化的空间里进行实验，但所有公司都在尝试突破对环境的要求，这是真正的考验。”杜筱悠说。她是上海交大附中的高一学生，即将进入 中国科学院 研究员的课题组，参与真实的科研项目。 这群女生是欧莱雅 “一代耀一代”科技女生赋能计划的参与者。对她们而言，这次WAIC之行不仅是一次科技展览参访，…"
