    "content": "IT之家 7 月 27 日消息，据央视新闻今日报道，近期，坐落在贵州南部大山深处的中国天眼 FAST 望远镜顺利完成了六根巨型国产钢丝绳的更换工作，开启了新一轮的观测。 鲜为人知的是，在 FAST 望远镜落成启用之前，我国射电天文研究长期面临困境，国内没有自主可控的观测设备。天文学家们只能长期依赖国外公开的数据开展研究，极大限制了我国在该领域前沿探索的主动权。 报道提到，经过我国科研团队不懈奋斗，2016 年 FAST 落成启用，截至目前， 该望远镜已经成功找到 1284 颗脉冲星 ，远超同时期国际上所有其他望远镜…"
