    "content": "据媒体报道，中国已开始生产自主研发的浸没式深紫外光刻机（DUV）。在美国考虑进一步收紧对外国光刻设备向中国出口以及在华维修服务的限制之际，这项技术可能为中国晶片制造商提供关键设备的替代来源。 路透社据美国科技媒体《The Information》报道，国产光刻机设备预计将在今年内交付给中国主要晶片制造商，包括中芯国际、华虹半导体和长鑫存储。知情人士没有透露这家获得国家支持的制造商身份。 报道指出，这类晶片制造关键设备长期以来由荷兰供应商阿斯麦（ASML）主导。这一突破最终可能对阿斯麦在中国市场的地位构成挑战，但国产…"
