    "description": "新华社北京7月27日电（记者罗鑫）经过系统性保护修缮与整治提升，位于北京中轴线上的正阳门城楼自27日起恢复向社会开放。据了解，自2024年7月27日申遗成功以来，北京中轴线上越来越多的遗产点恢复开放，吸引观众漫步中轴线、感受古都魅力。 正阳门城楼位于天安门广场南端，始建于明永乐十七年（1419年），明清时期与正阳门箭楼、瓮城等共同构成一组兼具防御性和礼仪性的城门建筑群。正阳门城楼1991年起对社会开放，2020年起因保护修缮暂停开放，2…",
    "content": "新华社北京7月27日电（记者罗鑫）经过系统性保护修缮与整治提升，位于北京中轴线上的正阳门城楼自27日起恢复向社会开放。据了解，自2024年7月27日申遗成功以来，北京中轴线上越来越多的遗产点恢复开放，吸引观众漫步中轴线、感受古都魅力。 正阳门城楼位于天安门广场南端，始建于明永乐十七年（1419年），明清时期与正阳门箭楼、瓮城等共同构成一组兼具防御性和礼仪性的城门建筑群。正阳门城楼1991年起对社会开放，2020年起因保护修缮暂停开放，2025年底完成修缮。 北京市文物局局长张立新介绍，北京中轴线各遗产点持续加强文化…"
