    "description": "BBC / 香港前民主党主席胡志伟 出狱后赴英面临遣返 香港前民主党主席、涉“47人案”被囚的胡志伟，不久前刑满出狱。他上周飞往英国，抵达伦敦后遭边境部队边境部队扣留近10小时。胡志伟接受BBC中文专访讲述当时情况，强调并无申请政治庇护。 胡志伟于7月22日清晨从香港飞抵伦敦希斯罗机场，以英国国民（海外）（BN(O)）护照入境，但被扣查。英国《泰晤士报》披露此事，并称他原拟申请政治庇护。胡志伟向BBC中文否认此说法，但确认英国边境部队实…",
    "content": "BBC / 香港前民主党主席胡志伟 出狱后赴英面临遣返 香港前民主党主席、涉“47人案”被囚的胡志伟，不久前刑满出狱。他上周飞往英国，抵达伦敦后遭边境部队边境部队扣留近10小时。胡志伟接受BBC中文专访讲述当时情况，强调并无申请政治庇护。 胡志伟于7月22日清晨从香港飞抵伦敦希斯罗机场，以英国国民（海外）（BN(O)）护照入境，但被扣查。英国《泰晤士报》披露此事，并称他原拟申请政治庇护。胡志伟向BBC中文否认此说法，但确认英国边境部队实际上已拒绝他入境，仅给予他七天“入境保释”（immigration bail）。…"
