    "content": "一个基因，一颗药，和很多家庭被改写的命运 这是一个关于“读懂”与“改写”的故事。 它的主角有三个： 一个潜伏在基因里的破坏者，一颗在实验室里被反复打磨的药，和一群本不该这么年轻就被肺癌击中的人。 故事的起点，是科学家在二十多年前意识到的一件几乎反直觉的事：在某些癌症身上，疯狂生长的背后，藏着一个致命的破绽。 很多肿瘤的失控，并不是一团彻底的混乱，而是被某个出了故障的基因死死踩住了“油门”。整个肿瘤的生长，高度依赖这一个开关—— 科学家把这种现象叫作“致癌基因成瘾”。这意味着，肿瘤最强大的地方，也可能正是它最脆弱的地…"
