    "description": "有这样一个场景，我们在 tmux 的一个窗口中分割了两个小窗口，一个写代码，一个执行命令，这中间可能需要来回切换窗口改代码，再执行同样的命令。 这时候可以使用 tmux 的命令 tmux send-keys -t ! Up Enter 向上一个分割的窗口(!)发送键盘指令： 上(Up), 回车（ Enter ），就可以重复执行上一次的命令。 再加个快捷键异步执行， 不用来回切换窗口了，非常方便，也不用安装什么插件。 nnoremap t…",
    "content": "有这样一个场景，我们在 tmux 的一个窗口中分割了两个小窗口，一个写代码，一个执行命令，这中间可能需要来回切换窗口改代码，再执行同样的命令。 这时候可以使用 tmux 的命令 tmux send-keys -t ! Up Enter 向上一个分割的窗口(!)发送键盘指令： 上(Up), 回车（ Enter ），就可以重复执行上一次的命令。 再加个快捷键异步执行， 不用来回切换窗口了，非常方便，也不用安装什么插件。 nnoremap &lt;silent&gt; &lt;Leader&gt;tt :call job…"
