    "content": "新华社利雅得7月27日电（记者王海洲）沙特阿拉伯国防部27日发表声明说，沙特防空部队当天拦截并摧毁了数架来自伊拉克方向、企图袭击沙特境内石油设施的无人机。 沙特国防部发言人图尔基·马利基说，沙特防空部队在过去数小时内拦截并摧毁数架无人机。这些无人机自伊拉克境内发射，试图袭击沙特东部地区和首都利雅得的石油设施。 马利基表示，沙特拥有维护国家安全、保卫自身及国家能力的合法权利，并保留在适当时间和地点作出回应的权利。 沙特外交部同日发表声明，对本国遭遇无人机袭击表示“最强烈谴责”，并敦促伊拉克政府采取措施，防止其领土被用…"
